class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.values = {}                   # key -> value
        self.order = []                    # keys, least recently used first

    def _touch(self, key):                 # move key to the most recent end: O(n)
        if key in self.order:
            self.order.remove(key)
        self.order.append(key)

    def get(self, key):
        if key not in self.values:
            return -1
        self._touch(key)
        return self.values[key]

    def put(self, key, value):
        self.values[key] = value
        self._touch(key)
        if len(self.order) > self.capacity:
            lru = self.order.pop(0)        # the front of the list is the least recent
            del self.values[lru]

class LRUCache {
    private final int capacity;
    private final Map<Integer, Integer> values = new HashMap<>();   // key -> value
    private final List<Integer> order = new ArrayList<>();          // keys, least recently used first

    public LRUCache(int capacity) { this.capacity = capacity; }

    private void touch(int key) {                                   // move key to the most recent end: O(n)
        order.remove(Integer.valueOf(key));
        order.add(key);
    }

    public int get(int key) {
        if (!values.containsKey(key)) return -1;
        touch(key);
        return values.get(key);
    }

    public void put(int key, int value) {
        values.put(key, value);
        touch(key);
        if (order.size() > capacity) {
            int lru = order.remove(0);                              // the front of the list is the least recent
            values.remove(lru);
        }
    }
}

class LRUCache {
    int capacity;
    unordered_map<int, int> values;          // key -> value
    vector<int> order;                       // keys, least recently used first

    void touch(int key) {                    // move key to the most recent end: O(n)
        auto it = find(order.begin(), order.end(), key);
        if (it != order.end()) order.erase(it);
        order.push_back(key);
    }
public:
    LRUCache(int capacity) : capacity(capacity) {}

    int get(int key) {
        if (!values.count(key)) return -1;
        touch(key);
        return values[key];
    }

    void put(int key, int value) {
        values[key] = value;
        touch(key);
        if ((int)order.size() > capacity) {
            values.erase(order.front());     // the front of the list is the least recent
            order.erase(order.begin());
        }
    }
};

