class LRUCache {
    private final int capacity;
    private final Map<Integer, Entry> map = new HashMap<>();   // key -> its node
    private final Entry head = new Entry(0, 0);                // head.next: most recently used
    private final Entry tail = new Entry(0, 0);                // tail.prev: least recently used

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    private void remove(Entry node) {                           // unlink a node in O(1)
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void addFront(Entry node) {                         // insert right after the head sentinel
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }

    public int get(int key) {
        Entry node = map.get(key);
        if (node == null) return -1;
        remove(node);                                           // it was just used: move it to the front
        addFront(node);
        return node.value;
    }

    public void put(int key, int value) {
        if (map.containsKey(key)) remove(map.get(key));
        Entry node = new Entry(key, value);
        map.put(key, node);
        addFront(node);
        if (map.size() > capacity) {
            Entry lru = tail.prev;                              // the least recently used is at the back
            remove(lru);
            map.remove(lru.key);
        }
    }
}

