class LRUCache {
    int capacity;
    unordered_map<int, Entry*> map;          // key -> its node
    Entry* head = new Entry(0, 0);           // head->next: most recently used
    Entry* tail = new Entry(0, 0);           // tail->prev: least recently used

    void remove(Entry* node) {               // unlink a node in O(1)
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    void addFront(Entry* node) {             // insert right after the head sentinel
        node->prev = head;
        node->next = head->next;
        head->next->prev = node;
        head->next = node;
    }
public:
    LRUCache(int capacity) : capacity(capacity) {
        head->next = tail;
        tail->prev = head;
    }

    int get(int key) {
        auto it = map.find(key);
        if (it == map.end()) return -1;
        Entry* node = it->second;
        remove(node);                        // it was just used: move it to the front
        addFront(node);
        return node->value;
    }

    void put(int key, int value) {
        auto it = map.find(key);
        if (it != map.end()) {               // update the value and move it to the front
            it->second->value = value;
            remove(it->second);
            addFront(it->second);
            return;
        }
        Entry* node = new Entry(key, value);
        map[key] = node;
        addFront(node);
        if ((int)map.size() > capacity) {
            Entry* lru = tail->prev;         // the least recently used is at the back
            remove(lru);
            map.erase(lru->key);
            delete lru;
        }
    }
};
